from pathlib import Path
from bs4 import BeautifulSoup
import html
R=Path(__file__).parent;D=R/'dist'
logo='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 390 100" role="img" aria-labelledby="title"><title id="title">La Zagara — Frutti di Sicilia</title><g transform="translate(48 48)"><path d="M0 6C-35-3-38-34-22-35C-6-36 0-14 0 6Z" fill="#173c2b"/><path d="M0 6C35-3 38-34 22-35C6-36 0-14 0 6Z" fill="#71976a"/><path d="M0 6C-28 20-28 44-9 40C5 36 4 17 0 6Z" fill="#71976a"/><path d="M0 6C28 20 28 44 9 40C-5 36-4 17 0 6Z" fill="#173c2b"/><circle cy="7" r="13" fill="#ee8139"/><circle cy="7" r="5" fill="#f7f5ed"/></g><text x="108" y="53" fill="#173c2b" font-family="Georgia,serif" font-size="46" letter-spacing="-2">la zagara<tspan fill="#ee8139">.</tspan></text><text x="111" y="77" fill="#173c2b" font-family="Arial,sans-serif" font-size="9" letter-spacing="4">FRUTTI DI SICILIA</text></svg>'''
(D/'assets/zagara-modern.svg').write_text(logo,encoding='utf8')
content={
'home':('UNA PASSIONE, MOLTE SFUMATURE','La qualità si coltiva.<br><em>Ogni giorno.</em>', [('La nostra origine','Gli agrumeti alle pendici dell’Etna e la produzione di uva tra Sicilia e Puglia raccontano un legame concreto con il territorio.'),('La nostra ricerca','L’innovazione varietale affianca l’esperienza agricola: dalle uve senza semi alle selezioni di arance Tarocco.'),('Il nostro impegno','Tutela del consumatore, attenzione all’ambiente e packaging EcoFriendly orientano il lavoro di La Zagara.')]),
'chi-siamo':('IL NOSTRO MODO DI ESSERE','Radici agricole.<br><em>Visione aperta.</em>', [('Produciamo','Esperienza nella coltivazione in serra e in campo aperto, con metodi tradizionali e naturali e attenzione alla genuinità.'),('Selezioniamo','Una gamma che comprende agrumi, uva da tavola, pomodori, patate, carote e orticoli, con cura per il valore del prodotto.'),('Commercializziamo','Un lavoro rivolto anche alla grande distribuzione estera, sostenuto da innovazione costante e controlli di qualità.')]),
'prodotti':('UNA GAMMA DA ESPLORARE','Quattro mondi.<br><em>Un’unica passione.</em>', [('Uva da tavola','Varietà standard ed esclusive, con e senza semi. Le schede presentano caratteristiche, selezioni e calendari.'),('Agrumi','Arance Moro, Tarocco, Sanguinello, Lane Late e Clementine Tacle; limoni Femminello Siracusano e Zagara Bianca.'),('Pomodori','Ciliegino, Datterino e Piccadilly: tre interpretazioni di un protagonista della cucina italiana.')]),
'gallery':('LE IMMAGINI RACCONTANO','Dentro i luoghi.<br><em>Vicino alle persone.</em>', [('Il prodotto','Colori, forme e dettagli dei frutti: la materia prima è il punto di partenza del nostro racconto.'),('Il lavoro','Uno sguardo sulle attività e sugli spazi in cui i prodotti vengono seguiti e lavorati.'),('Il territorio','Le fotografie dell’azienda restituiscono il legame tra produzione e luoghi. Apri ogni immagine per osservarla da vicino.')]),
'news':('LEGGERE IL CAMBIAMENTO','Esperienza sul campo.<br><em>Idee in movimento.</em>', [('Innovazione varietale','L’archivio racconta l’interesse di La Zagara per le varietà di uva senza semi e per l’evoluzione dei gusti.'),('Le stagioni','Le interviste spiegano come clima, maturazione e lavoro dei produttori incidano sulle campagne agricole.'),('I mercati','Gli articoli offrono una prospettiva sui rapporti con la distribuzione e sui mercati europei, mantenendo le date di pubblicazione.')]),
'contatti':('PREPARIAMO IL PROSSIMO PASSO','Una richiesta chiara.<br><em>Un dialogo migliore.</em>', [('Per i prodotti','Indica il prodotto e la varietà di interesse. Puoi aggiungere periodo, quantità indicative e destinazione.'),('Per le collaborazioni','Presenta la tua azienda e il tipo di collaborazione che immagini: aiuterà a inquadrare la richiesta.'),('Per incontrarci','Trovi indirizzo, telefono e indicazioni nella pagina. Contatta l’azienda per concordare una visita.')])}
def section(k,t,items):
 return '<section class="depth-section wrap"><div class="depth-heading"><span class="eyebrow">'+k+'</span><h2>'+t+'</h2></div><div class="depth-grid">'+''.join('<article><span class="depth-index">0'+str(i+1)+'</span><h3>'+a+'</h3><p>'+b+'</p></article>' for i,(a,b) in enumerate(items))+'</div></section>'
for f in D.rglob('index.html'):
 s=BeautifulSoup(f.read_text(encoding='utf8'),'html.parser');main=s.select_one('main')
 for im in s.select('.brand img,.footer-about img'):im['src']='/assets/zagara-modern.svg';im['alt']='La Zagara — Frutti di Sicilia'
 icon=s.select_one('link[rel=icon]')
 if icon:icon['href']='/assets/zagara-modern.svg';icon['type']='image/svg+xml'
 key=f.parent.name if f.parent!=D else 'home'
 if key in content and not s.select_one('.depth-section'):
  main.append(BeautifulSoup(section(*content[key]),'html.parser'))
 elif s.select_one('.varieties') and not s.select_one('.depth-section'):
  name=s.select_one('.product-hero-name').get_text(strip=True)
  main.append(BeautifulSoup(section('CONOSCERE PER SCEGLIERE','Ogni varietà,<br><em>la sua personalità.</em>',[('Caratteristiche','Esplora le schede di '+html.escape(name)+' per conoscere le differenze tra le selezioni presentate da La Zagara.'),('Stagionalità','Il calendario PDF aiuta a orientarsi nei periodi dei prodotti. Per disponibilità e forniture aggiornate, contatta l’azienda.'),('Il tuo progetto','Comunica varietà, periodo e destinazione di interesse: sono il punto di partenza per una richiesta commerciale.')]),'html.parser'))
 if key=='contatti' and not s.select_one('.contact-faq'):
  main.append(BeautifulSoup('''<section class="contact-faq wrap"><span class="eyebrow">INFORMAZIONI UTILI</span><h2>Prima di <em>scriverci.</em></h2><details><summary>Come invio una richiesta?</summary><p>Compila il modulo: il pulsante prepara una email nel tuo programma di posta. Potrai controllarla e confermare l’invio. Puoi anche scrivere direttamente a info@zagara.com.</p></details><details><summary>Dove trovo le varietà disponibili?</summary><p>Le pagine dei prodotti presentano la gamma e le varietà. Per conoscere la disponibilità attuale e concordare una fornitura, contatta La Zagara.</p></details><details><summary>Posso consultare i calendari?</summary><p>Sì. Nelle schede prodotto puoi aprire i calendari PDF di La Zagara, dedicati ai prodotti e all’uva da tavola.</p></details></section>''','html.parser'))
 f.write_text(str(s),encoding='utf8')
p=D/'style.css';css=p.read_text(encoding='utf8')
if '/* Depth edition */' not in css:
 p.write_text(css+'''\n/* Depth edition */
.brand{width:218px}.footer-about img{width:210px}.depth-section{padding:95px 0;border-top:1px solid var(--line)}.depth-heading{display:grid;grid-template-columns:1fr 2fr;gap:35px;margin-bottom:55px}.depth-heading .eyebrow{padding-top:12px}.depth-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:45px}.depth-grid article{position:relative;padding:28px 0;border-top:1px solid var(--line)}.depth-index{font:italic 55px var(--serif);color:#b7c2ac}.depth-grid h3{font:35px var(--serif);margin:18px 0}.depth-grid p{font-size:12px;line-height:1.95}.contact-faq{padding:20px 0 90px}.contact-faq h2{margin:20px 0 35px}.contact-faq details{border-top:1px solid var(--line);padding:23px 0}.contact-faq summary{font-size:15px}.contact-faq summary:after{content:'+';float:right}.contact-faq details[open] summary:after{content:'−'}.contact-faq p{max-width:750px;margin-top:18px;font-size:13px}.page-intro{background:radial-gradient(ellipse at right top,#ee81390b,transparent 65%)}.variety-card>div{box-shadow:0 20px 40px -32px #173c2b90}.product-card:hover .product-image{box-shadow:0 24px 40px -25px #173c2b90}.depth-grid article:hover .depth-index{color:var(--orange);transition:color .3s}@media(max-width:700px){.brand{width:180px}.depth-section{padding:55px 0}.depth-heading{display:block;margin-bottom:30px}.depth-heading h2{font-size:46px;margin-top:20px}.depth-grid{grid-template-columns:1fr;gap:15px}.depth-grid article{padding:20px 0}.depth-index{font-size:40px}.depth-grid h3{font-size:32px;margin:10px 0}.depth-grid p{font-size:13px}.contact-faq{padding-bottom:60px}}
''',encoding='utf8')
print('Updated logo and depth across pages')
